// ListViewEl: Rows built on demand: the builder is called for the rows in view, not for
// all of them.
type ListViewEl struct {
	box[*ListViewEl]
	count       int
	row         func(int) Element
	itemHeight  float64
	height      float64
	virtualized bool
	grow        float64
}

// ListView is a new list_view.
func ListView(count int, row func(int) Element) *ListViewEl {
	e := &ListViewEl{count: count, row: row, itemHeight: 24, virtualized: true}
	e.self = e
	return e
}

func (e *ListViewEl) ItemHeight(v float64) *ListViewEl { e.itemHeight = v; return e }
func (e *ListViewEl) Height(v float64) *ListViewEl     { e.height = v; return e }
func (e *ListViewEl) Virtualized(v bool) *ListViewEl   { e.virtualized = v; return e }
func (e *ListViewEl) Grow(v float64) *ListViewEl       { e.grow = v; return e }

func (e *ListViewEl) emit() int64 {
	el := door.El(kindListView)
	door.Int(el, kCount, int64(e.count))
	if row := e.row; row != nil {
		door.RowBuilder(el, kRow, func(i int64) int64 {
			r := row(int(i))
			if r == nil {
				return 0
			}
			return r.emit()
		})
	}
	if e.itemHeight != 24 {
		door.Num(el, kItemHeight, e.itemHeight)
	}
	if e.height != 0 {
		door.Num(el, kHeight, e.height)
	}
	if !e.virtualized {
		door.Bool(el, kVirtualized, e.virtualized)
	}
	if e.grow != 0 {
		door.Num(el, kGrow, e.grow)
	}
	e.rd.write(el)
	return door.End(el)
}

// TableEl: A table whose rows are built on demand, laid on tracks whose shares are
// `widths`. `on_select` receives the row clicked, `on_sort` the header.
type TableEl struct {
	box[*TableEl]
	columns    []string
	count      int
	row        func(int) Element
	widths     []float64
	itemHeight float64
	height     float64
	grow       float64
	selected   int
	onSelect   func(int)
	sort       int
	descending bool
	onSort     func(int)
}

// Table is a new table.
func Table(columns []string, count int, row func(int) Element) *TableEl {
	e := &TableEl{columns: columns, count: count, row: row, itemHeight: 24, selected: -1, sort: -1}
	e.self = e
	return e
}

func (e *TableEl) Widths(v ...float64) *TableEl  { e.widths = v; return e }
func (e *TableEl) ItemHeight(v float64) *TableEl { e.itemHeight = v; return e }
func (e *TableEl) Height(v float64) *TableEl     { e.height = v; return e }
func (e *TableEl) Grow(v float64) *TableEl       { e.grow = v; return e }
func (e *TableEl) Selected(v int) *TableEl       { e.selected = v; return e }
func (e *TableEl) OnSelect(v func(int)) *TableEl { e.onSelect = v; return e }
func (e *TableEl) Sort(v int) *TableEl           { e.sort = v; return e }
func (e *TableEl) Descending(v bool) *TableEl    { e.descending = v; return e }
func (e *TableEl) OnSort(v func(int)) *TableEl   { e.onSort = v; return e }

func (e *TableEl) emit() int64 {
	el := door.El(kindTable)
	for _, v := range e.columns {
		door.PushStr(el, kColumns, v)
	}
	door.Int(el, kCount, int64(e.count))
	if row := e.row; row != nil {
		door.RowBuilder(el, kRow, func(i int64) int64 {
			r := row(int(i))
			if r == nil {
				return 0
			}
			return r.emit()
		})
	}
	for _, v := range e.widths {
		door.PushNum(el, kWidths, v)
	}
	if e.itemHeight != 24 {
		door.Num(el, kItemHeight, e.itemHeight)
	}
	if e.height != 0 {
		door.Num(el, kHeight, e.height)
	}
	if e.grow != 0 {
		door.Num(el, kGrow, e.grow)
	}
	if e.selected != -1 {
		door.Int(el, kSelected, int64(e.selected))
	}
	if f := e.onSelect; f != nil {
		door.Handler(el, kOnSelect, func() { f(int(door.EventInt())) })
	}
	if e.sort != -1 {
		door.Int(el, kSort, int64(e.sort))
	}
	if e.descending {
		door.Bool(el, kDescending, e.descending)
	}
	if f := e.onSort; f != nil {
		door.Handler(el, kOnSort, func() { f(int(door.EventInt())) })
	}
	e.rd.write(el)
	return door.End(el)
}

