// CanvasEl: A grid of virtual pixels, painted by the commands written in its block. A
// color here is a NUMBER: the index of a color in `palette`, which is how
// drawing code written for a pixel machine ports line for line. `scale` is
// how many logical pixels one virtual pixel takes.
type CanvasEl struct {
	box[*CanvasEl]
	width      int
	height     int
	scale      int
	background int
	palette    []string
	paint      func(*Painter)
}

// Canvas is a new canvas.
func Canvas(width int, height int) *CanvasEl {
	e := &CanvasEl{width: width, height: height, scale: 1}
	e.self = e
	return e
}

func (e *CanvasEl) Scale(v int) *CanvasEl         { e.scale = v; return e }
func (e *CanvasEl) Background(v int) *CanvasEl    { e.background = v; return e }
func (e *CanvasEl) Palette(v ...string) *CanvasEl { e.palette = v; return e }

// Paint is what the canvas draws: the commands written on the painter
// it is handed, in order.
func (e *CanvasEl) Paint(f func(*Painter)) *CanvasEl { e.paint = f; return e }

func (e *CanvasEl) emit() int64 {
	el := door.El(kindCanvas)
	door.Int(el, kWidth, int64(e.width))
	door.Int(el, kHeight, int64(e.height))
	if e.scale != 1 {
		door.Int(el, kScale, int64(e.scale))
	}
	if e.background != 0 {
		door.Int(el, kBackground, int64(e.background))
	}
	for _, v := range e.palette {
		door.PushStr(el, kPalette, v)
	}
	if e.paint != nil {
		e.paint(&Painter{el: el})
	}
	e.rd.write(el)
	return door.End(el)
}

// Painter is what a canvas's Paint closure draws with. A command is not
// an element: it takes none of the keywords every element takes,
// nothing can click it, and it means nothing outside the canvas it was
// written in. Every coordinate is a whole virtual pixel and every color
// is a NUMBER, the index of a color in the canvas's palette.
type Painter struct{ el int64 }

func (p *Painter) Pixel(x int, y int, color int) {
	door.OpPixel(p.el, int64(x), int64(y), int64(color))
}
func (p *Painter) Line(x1 int, y1 int, x2 int, y2 int, color int) {
	door.OpLine(p.el, int64(x1), int64(y1), int64(x2), int64(y2), int64(color))
}
func (p *Painter) Rect(x int, y int, w int, h int, color int) {
	door.OpRect(p.el, int64(x), int64(y), int64(w), int64(h), int64(color))
}
func (p *Painter) RectOutline(x int, y int, w int, h int, color int) {
	door.OpRectOutline(p.el, int64(x), int64(y), int64(w), int64(h), int64(color))
}
func (p *Painter) Circle(x int, y int, r int, color int) {
	door.OpCircle(p.el, int64(x), int64(y), int64(r), int64(color))
}
func (p *Painter) CircleOutline(x int, y int, r int, color int) {
	door.OpCircleOutline(p.el, int64(x), int64(y), int64(r), int64(color))
}
func (p *Painter) Triangle(x1 int, y1 int, x2 int, y2 int, x3 int, y3 int, color int) {
	door.OpTriangle(p.el, int64(x1), int64(y1), int64(x2), int64(y2), int64(x3), int64(y3), int64(color))
}
func (p *Painter) TriangleOutline(x1 int, y1 int, x2 int, y2 int, x3 int, y3 int, color int) {
	door.OpTriangleOutline(p.el, int64(x1), int64(y1), int64(x2), int64(y2), int64(x3), int64(y3), int64(color))
}
func (p *Painter) Sprite(x int, y int, source string, u int, v int, w int, h int, colkey int, flipX bool, flipY bool) {
	door.OpSprite(p.el, int64(x), int64(y), source, int64(u), int64(v), int64(w), int64(h), int64(colkey), flipX, flipY)
}
func (p *Painter) PixelText(x int, y int, text string, color int) {
	door.OpPixelText(p.el, int64(x), int64(y), text, int64(color))
}
